const {chromium} = require('playwright');
const assert = require('node:assert/strict');
(async () => {
  const browser = await chromium.launch({headless: true, args: ['--no-sandbox']});
  const page = await browser.newPage({viewport: {width: 1440, height: 1000}, deviceScaleFactor: 1});
  const errors = [];
  page.on('pageerror', (error) => errors.push(error.message));
  await page.goto('http://localhost:5173');
  await page.getByRole('heading', {name:'С возвращением'}).waitFor();
  await page.screenshot({path: '/tmp/gravity-desktop.png', fullPage: true});
  await page.getByRole('button', {name: 'Войти', exact: true}).click();
  assert(await page.getByText('Введите email', {exact:true}).isVisible());
  assert(await page.locator('#email').evaluate(el => el === document.activeElement));
  await page.getByLabel('Email', {exact:true}).fill('invalid');
  await page.getByRole('button', {name:'Войти',exact:true}).click();
  assert(await page.getByText('Введите корректный email', {exact:true}).isVisible());
  await page.getByLabel('Email', {exact:true}).fill('test@example.com');
  await page.getByLabel('Пароль', {exact:true}).fill('test-password');
  await page.getByRole('button', {name:'Показать пароль',exact:true}).click();
  assert.equal(await page.locator('#password').getAttribute('type'), 'text');
  await page.getByRole('button', {name:'Скрыть пароль',exact:true}).click();
  assert.equal(await page.locator('#password').getAttribute('type'), 'password');
  await page.getByRole('checkbox', {name:'Запомнить меня'}).check();
  assert(await page.getByRole('checkbox', {name:'Запомнить меня'}).isChecked());
  await page.locator('#password').press('Enter');
  assert(await page.getByRole('status').isVisible());
  await page.getByRole('button', {name:'Включить тёмную тему'}).click();
  assert(await page.locator('.page-dark').isVisible());
  await page.screenshot({path: '/tmp/gravity-dark.png', fullPage:true});
  await page.getByRole('button', {name:'Включить светлую тему'}).click();
  await page.setViewportSize({width: 390,height: 844});
  await page.reload();
  await page.getByRole('heading', {name:'С возвращением'}).waitFor();
  await page.screenshot({path: '/tmp/gravity-mobile.png',fullPage:true});
  assert(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth));
  assert(await page.getByRole('button', {name:'Войти',exact:true}).isVisible());
  assert.deepEqual(errors, []);
  console.log('PASS: validation, focus, password visibility, remember checkbox, Enter submission, theme switching, mobile layout, no runtime errors');
  await browser.close();
})();
